```cpp
#include <Servo.h>

const int TRIG_PIN = 9;
const int ECHO_PIN = 10;
const int SERVO_PIN = 6;
const int OPEN_ANGLE = 90;
const int CLOSED_ANGLE = 0;
const int THRESHOLD_CM = 40;
const unsigned long CLOSE_DELAY = 2000;

Servo lid;
bool lidOpen = false;
bool waitingToClose = false;
unsigned long objectLeftAt = 0;

float readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  unsigned long duration = pulseIn(ECHO_PIN, HIGH, 30000UL);
  if (duration == 0) return -1;
  return duration * 0.0343f / 2.0f;
}

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  lid.attach(SERVO_PIN);
  lid.write(CLOSED_ANGLE);
}

void loop() {
  float distance = readDistanceCm();
  bool objectPresent = distance > 0 && distance <= THRESHOLD_CM;

  if (objectPresent) {
    if (!lidOpen) {
      lid.write(OPEN_ANGLE);
      lidOpen = true;
    }
    waitingToClose = false;
  } else if (lidOpen) {
    if (!waitingToClose) {
      objectLeftAt = millis();
      waitingToClose = true;
    }

    if (millis() - objectLeftAt >= CLOSE_DELAY) {
      lid.write(CLOSED_ANGLE);
      lidOpen = false;
      waitingToClose = false;
    }
  }

  delay(50);
}
```

A no-echo reading returns -1 and is treated as no valid nearby object. The 2-second close period uses millis(), not delay(2000), so the sensor continues checking whether the object returns.

